INSERT INTO module_questions (module_id, level, question, options, correct_index, explanation, xp_reward) VALUES
('state-machine','basic','What is a state machine?',ARRAY['System that transitions between states','System with no states','System with one state','Analog circuit'],0,'A state machine has states and transitions.',10),
('state-machine','basic','What is a state in a state machine?',ARRAY['A condition or mode of the system','A clock cycle','A voltage level','A gate output'],0,'A state represents a unique configuration.',10),
('state-machine','basic','What is a transition?',ARRAY['Change from one state to another','A clock pulse','A reset signal','A gate delay'],0,'Transitions occur based on inputs and current state.',10),
('state-machine','basic','What are the two types of state machines?',ARRAY['Mealy and Moore','Combinational and sequential','Synchronous and asynchronous','Digital and analog'],0,'Mealy: output depends on state+input. Moore: output depends on state only.',10),
('state-machine','basic','What is a Moore machine?',ARRAY['Output depends only on current state','Output depends on input only','Output depends on state and input','No output'],0,'Moore: output = f(state).',10),
('state-machine','basic','What is a Mealy machine?',ARRAY['Output depends on state and input','Output depends on state only','Output depends on input only','No output'],0,'Mealy: output = f(state, input).',10),
('state-machine','basic','What is a state diagram?',ARRAY['Visual representation of states and transitions','Circuit diagram','Truth table','Timing diagram'],0,'State diagram: nodes = states, arrows = transitions.',10),
('state-machine','basic','What is a state table?',ARRAY['Tabular form of state transitions','Truth table','K-map','Timing diagram'],0,'State table lists next state and output for each input.',10),
('state-machine','basic','What is the initial state?',ARRAY['Starting state of the machine','Final state','Any state','Reset state'],0,'The initial state is entered on reset/power-up.',10),
('state-machine','basic','What is a reset state?',ARRAY['State entered on system reset','Final state','Error state','Idle state'],0,'Reset brings the machine to a known starting state.',10),
('state-machine','basic','What is a clock in a state machine?',ARRAY['Signal that triggers state transitions','Power signal','Reset signal','Input signal'],0,'State changes occur on clock edges.',10),
('state-machine','basic','What is a synchronous state machine?',ARRAY['Transitions on clock edges','Transitions anytime','No clock','Asynchronous'],0,'Synchronous: all flip-flops share the same clock.',10),
('state-machine','basic','What is an asynchronous state machine?',ARRAY['Transitions without a clock','Transitions on clock','Synchronous','No transitions'],0,'Asynchronous: transitions happen immediately on input change.',10),
('state-machine','basic','What is a flip-flop?',ARRAY['1-bit memory element','Logic gate','Counter','Multiplexer'],0,'Flip-flops store state bits.',10),
('state-machine','basic','What does D flip-flop do?',ARRAY['Stores D input on clock edge','Inverts input','ANDs inputs','ORs inputs'],0,'D-FF: Q follows D on clock edge.',10),
('state-machine','basic','What does JK flip-flop do?',ARRAY['J=K=0 hold, J=K=1 toggle, else set/reset','Stores D','Inverts clock','Counts only'],0,'JK-FF: versatile, can hold, set, reset, toggle.',10),
('state-machine','basic','What does T flip-flop do?',ARRAY['Toggles output on T=1','Stores T','Inverts T','ANDs inputs'],0,'T-FF: Q toggles when T=1 on clock edge.',10),
('state-machine','basic','What does SR flip-flop do?',ARRAY['S=1 set, R=1 reset, S=R=0 hold','Stores D','Toggles','Inverts'],0,'SR-FF: S sets, R resets, S=R=1 forbidden.',10),
('state-machine','basic','What is the forbidden state of SR flip-flop?',ARRAY['S=1 and R=1 simultaneously','S=0 and R=0','S=1 and R=0','S=0 and R=1'],0,'S=R=1 produces invalid output (both Q and Q'' high).',10),
('state-machine','basic','How many flip-flops are needed for 8 states?',ARRAY['3','2','4','8'],0,'2^n ≥ 8, so n = 3 flip-flops.',10),
('state-machine','basic','How many flip-flops are needed for 5 states?',ARRAY['3','2','4','5'],0,'2^n ≥ 5, so n = 3 (2^3 = 8 ≥ 5).',10),
('state-machine','basic','How many flip-flops are needed for 16 states?',ARRAY['4','3','5','16'],0,'2^4 = 16, so n = 4.',10),
('state-machine','basic','How many states can 4 flip-flops represent?',ARRAY['16','8','4','32'],0,'2^4 = 16 states.',10),
('state-machine','basic','What is a counter?',ARRAY['State machine that cycles through states','Adder circuit','Comparator','Multiplexer'],0,'Counters are a common type of state machine.',10),
('state-machine','basic','What is an up counter?',ARRAY['Counts 0, 1, 2, ..., max, 0, ...','Counts down only','Counts randomly','Stays at 0'],0,'Up counter increments on each clock.',10),
('state-machine','basic','What is a down counter?',ARRAY['Counts max, max-1, ..., 0, max, ...','Counts up only','Counts randomly','Stays at max'],0,'Down counter decrements on each clock.',10),
('state-machine','basic','What is an up/down counter?',ARRAY['Can count up or down based on control','Counts up only','Counts down only','Stays fixed'],0,'Up/down counter: direction controlled by input.',10),
('state-machine','basic','What is a modulo-N counter?',ARRAY['Counts 0 to N-1 then wraps','Counts to N','Counts 0 to infinity','Counts down only'],0,'Mod-N counter has N states (0 to N-1).',10),
('state-machine','basic','What is a mod-10 counter?',ARRAY['Counts 0-9 (decade counter)','Counts 0-10','Counts 0-99','Counts 0-100'],0,'Mod-10: 0,1,2,...,9,0,1,...',10),
('state-machine','basic','What is a ripple counter?',ARRAY['Flip-flops cascade, carry ripples','All FFs clocked simultaneously','No clock','Synchronous counter'],0,'Ripple (asynchronous) counter: each FF triggers the next.',10),
('state-machine','basic','What is a synchronous counter?',ARRAY['All flip-flops share same clock','Each FF triggers next','No clock','Ripple counter'],0,'Synchronous counter: all FFs update simultaneously.',10),
('state-machine','basic','What is the advantage of synchronous counter?',ARRAY['No ripple delay','Simpler design','Fewer gates','Lower power'],0,'Synchronous counters avoid cumulative propagation delay.',10),
('state-machine','basic','What is a ring counter?',ARRAY['Shift register with feedback','Binary counter','Ripple counter','Johnson counter'],0,'Ring counter: Q of last FF feeds D of first.',10),
('state-machine','basic','How many states does an n-bit ring counter have?',ARRAY['n','2^n','n-1','2n'],0,'Ring counter: n states (one-hot encoding).',10),
('state-machine','basic','What is a Johnson counter?',ARRAY['Ring counter with inverted feedback','Binary counter','Ripple counter','Decade counter'],0,'Johnson (twisted ring): inverted feedback doubles states.',10),
('state-machine','basic','How many states does an n-bit Johnson counter have?',ARRAY['2n','n','2^n','n²'],0,'Johnson counter: 2n states.',10),
('state-machine','basic','What is a shift register?',ARRAY['Chain of flip-flops shifting data','Counter','Adder','Comparator'],0,'Shift registers store and shift data bit-by-bit.',10),
('state-machine','basic','What is SISO shift register?',ARRAY['Serial In, Serial Out','Parallel In, Parallel Out','Serial In, Parallel Out','Parallel In, Serial Out'],0,'SISO: data enters and exits one bit at a time.',10),
('state-machine','basic','What is SIPO shift register?',ARRAY['Serial In, Parallel Out','SISO','PISO','PIPO'],0,'SIPO: serial input, read all bits in parallel.',10),
('state-machine','basic','What is PISO shift register?',ARRAY['Parallel In, Serial Out','SISO','SIPO','PIPO'],0,'PISO: load all bits, shift out serially.',10),
('state-machine','basic','What is PIPO shift register?',ARRAY['Parallel In, Parallel Out','SISO','SIPO','PISO'],0,'PIPO: parallel load and parallel read.',10),
('state-machine','basic','What is a finite state machine (FSM)?',ARRAY['State machine with finite number of states','State machine with infinite states','Analog state machine','No states'],0,'FSM: finite states, deterministic transitions.',10),
('state-machine','basic','What is a deterministic FSM?',ARRAY['Each input has exactly one transition','Multiple transitions per input','Random transitions','No transitions'],0,'Deterministic: one next state per (state, input).',10),
('state-machine','basic','What is a nondeterministic FSM (NFA)?',ARRAY['Multiple possible transitions per input','One transition per input','No transitions','Random states'],0,'NFA: can transition to multiple states simultaneously.',10),
('state-machine','basic','What is a Mealy output?',ARRAY['Associated with transitions','Associated with states','No output','Constant output'],0,'Mealy outputs appear on transition arcs.',10),
('state-machine','basic','What is a Moore output?',ARRAY['Associated with states','Associated with transitions','No output','Input-dependent output'],0,'Moore outputs appear inside state nodes.',10),
('state-machine','basic','Which machine type generally has fewer states?',ARRAY['Mealy','Moore','Same','Depends on input'],0,'Mealy often needs fewer states (output on transitions).',10),
('state-machine','basic','Which machine type is easier to design?',ARRAY['Moore (simpler output logic)','Mealy','Both equally','Neither'],0,'Moore: output depends only on state, simpler logic.',10),
('state-machine','basic','What is a state encoding?',ARRAY['Assigning binary codes to states','Encoding inputs','Encoding outputs','Encoding transitions'],0,'State encoding: binary, one-hot, Gray code.',10),
('state-machine','basic','What is one-hot encoding?',ARRAY['One bit per state','Binary encoding','Gray code','BCD encoding'],0,'One-hot: n states use n flip-flops, one bit high at a time.',10);INSERT INTO module_questions (module_id, level, question, options, correct_index, explanation, xp_reward) VALUES
('state-machine','intermediate','What is state minimization?',ARRAY['Merging equivalent states','Adding more states','Removing inputs','Reducing outputs'],0,'Equivalent states produce same outputs and transitions.',15),
('state-machine','intermediate','What are equivalent states?',ARRAY['States with same outputs and next states for all inputs','States with same name','States with same encoding','Adjacent states'],0,'Two states are equivalent if they behave identically.',15),
('state-machine','intermediate','What is the state minimization algorithm?',ARRAY['Partition refinement','Binary search','Bubble sort','Dijkstra''s'],0,'Partition refinement merges equivalent states.',15),
('state-machine','intermediate','What is a partition in state minimization?',ARRAY['Group of states that may be equivalent','Group of inputs','Group of outputs','Group of transitions'],0,'Partitions are iteratively refined to find equivalents.',15),
('state-machine','intermediate','What is state assignment?',ARRAY['Assigning binary codes to states','Assigning inputs','Assigning outputs','Assigning transitions'],0,'State assignment affects circuit complexity.',15),
('state-machine','intermediate','What are common state assignment strategies?',ARRAY['Binary, Gray, one-hot, random','Sequential, parallel','Ascending, descending','Odd, even'],0,'Different encodings optimize different metrics.',15),
('state-machine','intermediate','What is a Mealy-to-Moore conversion?',ARRAY['Adding states to move outputs from arcs to nodes','Removing states','Adding inputs','Removing outputs'],0,'Mealy→Moore: split states so output depends only on state.',15),
('state-machine','intermediate','What is a Moore-to-Mealy conversion?',ARRAY['Moving outputs from states to transitions','Adding states','Removing transitions','Adding inputs'],0,'Moore→Mealy: move output to incoming transition arc.',15),
('state-machine','intermediate','What is a sequence detector?',ARRAY['FSM that recognizes a specific input pattern','FSM that counts','FSM that adds','FSM that divides'],0,'Sequence detectors find specific bit patterns.',15),
('state-machine','intermediate','How many states for a Mealy sequence detector for ''101''?',ARRAY['4','3','5','2'],0,'Mealy ''101'' detector: S0, S1, S2, S3 (found).',15),
('state-machine','intermediate','How many states for a Moore sequence detector for ''101''?',ARRAY['5','4','3','2'],0,'Moore needs one extra state for output delay.',15),
('state-machine','intermediate','What is a Mealy sequence detector advantage?',ARRAY['Fewer states than Moore','More states','Faster clock','Less logic'],0,'Mealy uses fewer states but output can glitch.',15),
('state-machine','intermediate','What is a glitch in Mealy machines?',ARRAY['Brief incorrect output during state transition','Permanent error','Clock error','Reset error'],0,'Mealy output can change mid-transition (asynchronous).',15),
('state-machine','intermediate','How to avoid Mealy glitches?',ARRAY['Register the output or use Moore machine','Add more states','Increase clock','Remove inputs'],0,'Registered Mealy or Moore avoids glitches.',15),
('state-machine','intermediate','What is a traffic light controller?',ARRAY['FSM controlling light sequences','Analog circuit','Combinational logic','Counter only'],0,'Traffic lights cycle: green→yellow→red→green.',15),
('state-machine','intermediate','How many states does a simple traffic light controller have?',ARRAY['4 (G, Y, R in two directions)','2','3','6'],0,'Two directions: NS-green, NS-yellow, EW-green, EW-yellow.',15),
('state-machine','intermediate','What is a vending machine controller?',ARRAY['FSM accepting coins and dispensing products','Counter','Adder','Comparator'],0,'Vending machines track credit and product selection.',15),
('state-machine','intermediate','What is an elevator controller?',ARRAY['FSM managing floor and door states','Counter','Timer','Comparator'],0,'Elevator: states for idle, moving, door open/closed.',15),
('state-machine','intermediate','What is a deadlock state?',ARRAY['State with no exit transitions','Initial state','Final state','Error state'],0,'Deadlock: machine stuck, cannot progress.',15),
('state-machine','intermediate','What is a livelock in an FSM?',ARRAY['Machine cycles without making progress','Machine is stuck','Machine resets','Machine stops'],0,'Livelock: active but no useful work done.',15),
('state-machine','intermediate','What is a reachability analysis?',ARRAY['Finding all states reachable from initial','Counting states','Minimizing states','Encoding states'],0,'Reachability: BFS/DFS from initial state.',15),
('state-machine','intermediate','What is an unreachable state?',ARRAY['State never entered from initial state','State with no inputs','State with no outputs','Final state'],0,'Unreachable states can be removed.',15),
('state-machine','intermediate','What is a state transition table?',ARRAY['Maps (state, input) → (next state, output)','Maps inputs to outputs','Maps states to codes','Maps clocks to transitions'],0,'Transition table fully specifies FSM behavior.',15),
('state-machine','intermediate','What is the next-state equation?',ARRAY['Boolean function for each flip-flop input','Clock equation','Output equation','Reset equation'],0,'Next-state eq: D_i = f(current state, inputs).',15),
('state-machine','intermediate','What is the output equation?',ARRAY['Boolean function for FSM outputs','Next-state function','Clock function','Reset function'],0,'Output eq: Y = f(state) [Moore] or f(state, input) [Mealy].',15),
('state-machine','intermediate','What is a D flip-flop input equation?',ARRAY['D = next-state function','D = current state','D = clock','D = output'],0,'For D-FF: D input = desired next state.',15),
('state-machine','intermediate','What is a JK flip-flop input equation?',ARRAY['J and K derived from next-state table','D = next state','T = toggle','S = set'],0,'JK: J=1 set, K=1 reset, J=K=1 toggle, J=K=0 hold.',15),
('state-machine','intermediate','What is a T flip-flop input equation?',ARRAY['T = 1 when state should change','T = 0 always','T = clock','T = output'],0,'T-FF: T=1 toggles, T=0 holds.',15),
('state-machine','intermediate','What is excitation table?',ARRAY['Table showing FF inputs needed for each transition','Truth table','State table','K-map'],0,'Excitation tables give required inputs for state changes.',15),
('state-machine','intermediate','What is the D-FF excitation table?',ARRAY['D = next state (always)','D = 0','D = 1','D = current state'],0,'D-FF: D = Q(next), regardless of current.',15),
('state-machine','intermediate','What is the JK-FF excitation for Q→Q''?',ARRAY['J=1, K=1','J=0, K=0','J=1, K=0','J=0, K=1'],0,'Toggle: J=K=1.',15),
('state-machine','intermediate','What is the JK-FF excitation for Q→Q (hold)?',ARRAY['J=0, K=0','J=1, K=1','J=1, K=0','J=0, K=1'],0,'Hold: J=K=0.',15),
('state-machine','intermediate','What is the T-FF excitation for Q→Q''?',ARRAY['T=1','T=0','T=Q','T=Q'''],0,'Toggle: T=1.',15),
('state-machine','intermediate','What is the T-FF excitation for Q→Q (hold)?',ARRAY['T=0','T=1','T=Q','T=Q'''],0,'Hold: T=0.',15),
('state-machine','intermediate','What is a K-map for state machine design?',ARRAY['Minimizes next-state and output equations','Counts states','Encodes states','Tests states'],0,'K-maps simplify Boolean expressions for FF inputs.',15),
('state-machine','intermediate','What is a binary counter with parallel load?',ARRAY['Counter that can be preset to any value','Counter that only counts up','Counter that only counts down','Ripple counter'],0,'Parallel load: load arbitrary value, then count.',15),
('state-machine','intermediate','What is a self-starting counter?',ARRAY['Eventually reaches valid counting sequence from any state','Starts at 0','Starts at max','Never starts'],0,'Self-starting: all unused states lead to valid states.',15),
('state-machine','intermediate','What is a non-self-starting counter?',ARRAY['May get stuck in unused states','Always starts correctly','Counts backwards','Never counts'],0,'Non-self-starting: unused states may form deadlock cycles.',15),
('state-machine','intermediate','How do you make a counter self-starting?',ARRAY['Map unused states to valid states','Add more flip-flops','Remove flip-flops','Increase clock speed'],0,'Design next-state logic to redirect unused states.',15),
('state-machine','intermediate','What is a Gray code counter?',ARRAY['Counter using Gray code encoding','Binary counter','One-hot counter','BCD counter'],0,'Gray code: one bit changes per transition, no glitches.',15),
('state-machine','intermediate','What is the advantage of Gray code in state machines?',ARRAY['Only one bit changes per transition','Fewer states','Less power','Higher speed'],0,'Single bit change avoids decoding glitches.',15),
('state-machine','intermediate','What is a clock divider?',ARRAY['Circuit that divides clock frequency','Amplifies clock','Generates clock','Buffers clock'],0,'Clock divider: toggle FF divides by 2.',15),
('state-machine','intermediate','What division ratio does a single toggle FF give?',ARRAY['Divide by 2','Divide by 4','Divide by 8','Divide by 10'],0,'One T-FF with T=1 divides clock by 2.',15),
('state-machine','intermediate','How many FFs for divide-by-16?',ARRAY['4','2','3','8'],0,'2^4 = 16, so 4 toggle FFs.',15),
('state-machine','intermediate','What is a digital clock manager (DCM)?',ARRAY['PLL/DLL for clock synthesis and phase shifting','Counter','Divider','Buffer'],0,'DCM: phase shifting, frequency synthesis, deskew.',15),
('state-machine','intermediate','What is clock domain crossing?',ARRAY['Transferring data between different clock domains','Clock division','Clock buffering','Clock generation'],0,'CDC requires synchronizers to prevent metastability.',15),
('state-machine','intermediate','What is a two-flop synchronizer?',ARRAY['Two flip-flops in series for CDC','Two flip-flops in parallel','Two flip-flops with feedback','Single flip-flop'],0,'Two-stage synchronizer reduces metastability probability.',15),
('state-machine','intermediate','What is the MTBF of a synchronizer?',ARRAY['Mean Time Between Failures from metastability','Maximum Time Before Failure','Minimum Time Between Fixes','Mean Toggle Bit Frequency'],0,'MTBF depends on clock frequency, data rate, and FF parameters.',15),
('state-machine','intermediate','What is asynchronous reset?',ARRAY['Reset independent of clock','Reset synchronized with clock','No reset','Clock-dependent reset'],0,'Async reset: immediate effect, but may cause metastability.',15),
('state-machine','intermediate','What is synchronous reset?',ARRAY['Reset only takes effect on clock edge','Reset is immediate','No reset needed','Reset is asynchronous'],0,'Sync reset: safer, avoids reset deassertion metastability.',15);INSERT INTO module_questions (module_id, level, question, options, correct_index, explanation, xp_reward) VALUES
('state-machine','advanced','What is a Huffman encoding for FSM design?',ARRAY['Minimal state assignment method','Compression algorithm','State encoding type','Gate-level optimization'],0,'Huffman: minimal logic via state assignment heuristics.',20),
('state-machine','advanced','What is the difference between Mealy and Moore delay?',ARRAY['Mealy: same-cycle output; Moore: next-cycle output','Moore: same-cycle','No difference','Mealy: delayed'],0,'Mealy output appears in the same cycle as input.',20),
('state-machine','advanced','What is a UML statechart?',ARRAY['Hierarchical state machine notation','Truth table','K-map','Timing diagram'],0,'UML statecharts support nested/orthogonal states.',20),
('state-machine','advanced','What is a hierarchical state machine?',ARRAY['States can contain sub-states','States are all flat','States have no hierarchy','States are parallel only'],0,'HSM: nested states, shared transitions at parent level.',20),
('state-machine','advanced','What is an orthogonal (concurrent) state machine?',ARRAY['Multiple independent state regions','Single state region','No states','Hierarchical states'],0,'Orthogonal regions run concurrently and independently.',20),
('state-machine','advanced','What is a history state in HSM?',ARRAY['Remembers last active sub-state','Initial state','Final state','Error state'],0,'History pseudo-state restores previous sub-state on re-entry.',20),
('state-machine','advanced','What is a guard condition on a transition?',ARRAY['Condition that must be true for transition','Clock condition','Reset condition','Output condition'],0,'Guard: boolean expression on transition arc.',20),
('state-machine','advanced','What is an action in a state machine?',ARRAY['Activity executed during transition or state','Input signal','Output signal','Clock signal'],0,'Actions: entry, exit, transition, or internal actions.',20),
('state-machine','advanced','What is a transition action vs state action?',ARRAY['Transition action: on arc; state action: in state','Both same','Transition action only','State action only'],0,'Mealy-like: transition actions. Moore-like: state actions.',20),
('state-machine','advanced','What is a Petri net?',ARRAY['Concurrent state machine with tokens','Sequential FSM','Truth table','K-map'],0,'Petri nets model concurrency with places, transitions, tokens.',20),
('state-machine','advanced','What is a marked place in a Petri net?',ARRAY['Place indicating completion','Initial place','Token-free place','Transition place'],0,'Marked places represent final/accepting states.',20),
('state-machine','advanced','What is a Timed Automaton?',ARRAY['State machine with clock constraints','State machine with no clock','Analog state machine','Digital counter'],0,'Timed automata: transitions have time guards (real-time systems).',20),
('state-machine','advanced','What is a Buchi automaton?',ARRAY['Automaton accepting infinite sequences','Accepts finite sequences','No acceptance','Single state'],0,'Buchi: accepts if some state visited infinitely often.',20),
('state-machine','advanced','What is a regular expression equivalent to?',ARRAY['Finite automaton (DFA/NFA)','Pushdown automaton','Turing machine','Infinite state machine'],0,'Regular expressions = regular languages = finite automata.',20),
('state-machine','advanced','What is the pumping lemma for regular languages?',ARRAY['All regular languages can be ''pumped''','All languages are regular','No pumping needed','Infinite pumping'],0,'Pumping lemma: used to prove non-regularity.',20),
('state-machine','advanced','What is the Myhill-Nerode theorem?',ARRAY['Language is regular iff finite equivalence classes','All languages are regular','DFA minimization','State encoding'],0,'Myhill-Nerode: regularity via distinguishable string pairs.',20),
('state-machine','advanced','What is the difference between DFA and NFA?',ARRAY['NFA allows multiple transitions; DFA has one','DFA has multiple transitions','No difference','NFA is deterministic'],0,'DFA: one transition per (state, input). NFA: zero or more.',20),
('state-machine','advanced','What is epsilon (λ) transition in NFA?',ARRAY['Transition without consuming input','Transition consuming input','No transition','Error transition'],0,'Epsilon transitions allow state changes without input.',20),
('state-machine','advanced','What is the subset construction?',ARRAY['Converts NFA to DFA','Converts DFA to NFA','Minimizes DFA','Encodes states'],0,'Subset construction: DFA states = sets of NFA states.',20),
('state-machine','advanced','What is the worst-case DFA size from NFA with n states?',ARRAY['2^n','n','n²','n!'],0,'Subset construction can produce up to 2^n DFA states.',20),
('state-machine','advanced','What is Hopcroft''s algorithm?',ARRAY['DFA minimization in O(n log n)','NFA to DFA','State encoding','DFA construction'],0,'Hopcroft: partition-based DFA minimization.',20),
('state-machine','advanced','What is Brzozowski''s algorithm?',ARRAY['DFA minimization via reversal and determinization','DFA construction','NFA simulation','State encoding'],0,'Brzozowski: reverse + determinize + reverse + determinize.',20),
('state-machine','advanced','What is a pushdown automaton (PDA)?',ARRAY['Automaton with a stack','Automaton with no memory','DFA with output','NFA with output'],0,'PDA recognizes context-free languages.',20),
('state-machine','advanced','What is a Turing machine?',ARRAY['Automaton with infinite tape','DFA','NFA','PDA'],0,'Turing machines recognize recursively enumerable languages.',20),
('state-machine','advanced','What is the Church-Turing thesis?',ARRAY['Turing machines capture effective computation','All problems are decidable','All languages are regular','All machines are equivalent'],0,'Church-Turing: TM = universal model of computation.',20),
('state-machine','advanced','What is the halting problem?',ARRAY['Undecidable whether a TM halts','Always halts','Never halts','Sometimes halts'],0,'Halting problem: proven undecidable by Turing.',20),
('state-machine','advanced','What is a Mealy machine conversion to state diagram?',ARRAY['Outputs on transition arcs','Outputs in state nodes','No outputs','Outputs separate'],0,'Mealy: output labels on arcs between states.',20),
('state-machine','advanced','What is a Moore machine conversion to state diagram?',ARRAY['Outputs in state nodes','Outputs on arcs','No outputs','Outputs separate'],0,'Moore: output labels inside state circles.',20),
('state-machine','advanced','What is state encoding for FPGA optimization?',ARRAY['One-hot preferred for FPGAs','Binary preferred','Gray preferred','Random preferred'],0,'FPGAs have many flip-flops, making one-hot efficient.',20),
('state-machine','advanced','What is state encoding for ASIC optimization?',ARRAY['Binary or Gray preferred','One-hot preferred','Random','Sequential'],0,'ASICs: minimize flip-flops, prefer compact encoding.',20),
('state-machine','advanced','What is a redundant state?',ARRAY['State that can be merged with another','State with no inputs','State with no outputs','Final state'],0,'Redundant states are equivalent and can be merged.',20),
('state-machine','advanced','What is the implication chart method?',ARRAY['State minimization technique','State encoding method','State diagram method','State table method'],0,'Implication chart: pairwise state equivalence testing.',20),
('state-machine','advanced','What is a state graph traversal for verification?',ARRAY['Model checking all reachable states','Simulation only','Testing only','Formal proof only'],0,'Model checking: exhaustively verify FSM properties.',20),
('state-machine','advanced','What is SPIN model checker?',ARRAY['Tool for verifying FSM properties','Circuit simulator','State encoder','K-map tool'],0,'SPIN: verifies LTL/never-claims on Promela models.',20),
('state-machine','advanced','What is LTL (Linear Temporal Logic)?',ARRAY['Logic for expressing time-dependent properties','Logic for circuits','Logic for gates','Logic for states'],0,'LTL: □ (always), ◇ (eventually), ○ (next), U (until).',20),
('state-machine','advanced','What is CTL (Computation Tree Logic)?',ARRAY['Logic for branching time properties','Linear time logic','No temporal logic','State logic'],0,'CTL: A (all paths), E (exists path), G (globally), F (future).',20),
('state-machine','advanced','What is the difference between LTL and CTL?',ARRAY['LTL: linear time; CTL: branching time','No difference','LTL is stronger','CTL is weaker'],0,'LTL: one path at a time. CTL: quantifies over paths.',20),
('state-machine','advanced','What is a fairness constraint?',ARRAY['Condition that must hold infinitely often','Condition that holds once','No condition','Reset condition'],0,'Fairness: e.g., ''request always eventually granted.''',20),
('state-machine','advanced','What is a deadlock-free FSM?',ARRAY['No state with no outgoing transitions','All states have inputs','All states have outputs','All states reachable'],0,'Deadlock-free: every state has at least one valid transition.',20),
('state-machine','advanced','What is a liveness property?',ARRAY['Something good eventually happens','Something bad never happens','System is stable','System is fast'],0,'Liveness: ''eventually reach goal state'' (progress).',20),
('state-machine','advanced','What is a safety property?',ARRAY['Something bad never happens','Something good eventually happens','System is fast','System is stable'],0,'Safety: ''never enter error state'' (invariance).',20),
('state-machine','advanced','What is a hazard-free FSM design?',ARRAY['No glitches in output or state','Fast FSM','Small FSM','Low-power FSM'],0,'Hazard-free: Gray code + Moore outputs avoid glitches.',20),
